page='''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>RentaSmart | Panel</title><style>
:root{--ink:#16324f;--blue:#168aad;--pale:#eff5f8;--muted:#536a7f}*{box-sizing:border-box}body{margin:0;background:#f4f7f9;color:#172b3d;font:15px/1.5 Segoe UI,Arial,sans-serif}.wrap{max-width:1120px;margin:auto;padding:28px}header{background:var(--ink);color:white;padding:26px 30px;border-radius:16px}h1{margin:0 0 4px;font-size:26px}header p{margin:0;color:#d6e3ee}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.card,.panel{background:white;border-radius:13px;padding:18px;box-shadow:0 2px 10px #1832470d}.label{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.05em}.value{font-size:24px;font-weight:700;color:var(--ink);margin-top:5px}.panel{margin:14px 0}.row{display:flex;gap:14px;align-items:end;flex-wrap:wrap}label{font-size:13px;color:var(--muted);display:block;margin-bottom:4px}select,input{padding:9px 11px;border:1px solid #c7d4de;border-radius:8px;background:white;font:inherit}.result{font-size:21px;color:var(--blue);font-weight:700}.note{background:#fff4d6;color:#684c0b;border-left:4px solid #e4bf51;padding:13px 15px;border-radius:8px}.small{font-size:12px;color:var(--muted)}svg{width:100%;height:auto;max-height:510px}.tablewrap{max-height:380px;overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:8px;border-bottom:1px solid #e1e8ed}th{position:sticky;top:0;background:#e9f0f5;color:var(--ink)}@media(max-width:760px){.grid{grid-template-columns:repeat(2,1fr)}.wrap{padding:14px}.value{font-size:18px}}
</style></head><body><main class="wrap"><header><h1>RentaSmart</h1><p>Estimación orientativa de renta anunciada por colonia · corte 22 nov 2026</p></header><section class="grid" id="kpis"></section><section class="panel"><h2>Explora las medianas de la muestra</h2><div class="row"><div><label for="kind">Tipo de vivienda</label><select id="kind"><option value="todos">Todos</option><option value="departamento">Departamento</option><option value="casa">Casa</option></select></div><div><label for="search">Buscar colonia</label><input id="search" placeholder="Escribe una colonia"></div></div><div id="chart"></div><div class="small">Cada punto es la mediana agregada de una colonia y tipo de vivienda; no representa un anuncio individual.</div></section><section class="panel"><h2>Calculadora experimental</h2><div class="row"><div><label for="area">Superficie (m²)</label><input id="area" type="number" min="15" max="500" value="70"></div><div><label for="predtype">Tipo</label><select id="predtype"><option value="departamento">Departamento</option><option value="casa">Casa</option></select></div><div class="result" id="prediction"></div></div><p class="small">Modelo lineal sobre logaritmos, con área mediana y tipo. Se entrenó con agregados de colonias distintas a las de prueba. No es avalúo ni recomendación de precio.</p></section><section class="panel"><h2>Colonias en la muestra</h2><div class="tablewrap"><table><thead><tr><th>Zona</th><th>Tipo</th><th>Avisos</th><th>Área mediana</th><th>Renta mediana</th><th>P25–P75</th></tr></thead><tbody id="rows"></tbody></table></div></section><div class="note"><b>Uso responsable.</b> Precios solicitados, no precios de cierre. La cobertura depende de anuncios publicados en portales y no representa toda la vivienda arrendada. El modelo no puntúa personas ni recomienda fijar rentas. Los resultados pueden variar por colonia; consulta muestra y limitaciones antes de interpretar.</div><p class="small">Fuente: Aptología (2026), datos abiertos CC BY 4.0. Agregados sin anuncios individuales ni datos personales. Este panel es un prototipo local; no está publicado en una dirección pública.</p></main><script>
const D=__DATA__,M=D.metrics,R=D.records;const fmt=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0}).format(n);const kind=document.querySelector('#kind'),search=document.querySelector('#search');
function filtered(){let k=kind.value,s=search.value.toLocaleLowerCase('es');return R.filter(r=>(k==='todos'||r.tipo===k)&&r.zona.toLocaleLowerCase('es').includes(s))}
function draw(){let a=filtered();let med=a.length?a.map(x=>x.mediana).sort((x,y)=>x-y)[Math.floor(a.length/2)]:0;document.querySelector('#kpis').innerHTML=[['Colonias y tipo',a.length],['Mediana observada',med?fmt(med):'—'],['MAE de prueba',fmt(M.MAE_MXN)],['R² de prueba',M.R2.toFixed(3)]].map(x=>`<article class="card"><div class="label">${x[0]}</div><div class="value">${x[1]}</div></article>`).join('');
let W=880,H=410,L=66,T=26,PW=790,PH=315,xmax=Math.max(200,...a.map(x=>x.mediana_area_m2)),ymax=Math.max(50000,...a.map(x=>x.mediana));let dots=a.map(x=>{let px=L+x.mediana_area_m2/xmax*PW,py=T+PH-x.mediana/ymax*PH;return `<circle cx="${px}" cy="${py}" r="4" fill="#168aad" opacity=".58"><title>${x.zona} · ${x.tipo}: ${fmt(x.mediana)}, ${x.mediana_area_m2} m²</title></circle>`}).join('');let grid='';for(let i=0;i<5;i++){let y=T+PH-i*PH/4;grid+=`<line x1="${L}" y1="${y}" x2="${L+PW}" y2="${y}" stroke="#dce5eb"/><text x="${L-8}" y="${y+4}" text-anchor="end" font-size="11" fill="#536a7f">${fmt(ymax*i/4)}</text>`}document.querySelector('#chart').innerHTML=`<svg viewBox="0 0 ${W} ${H}">${grid}<line x1="${L}" y1="${T+PH}" x2="${L+PW}" y2="${T+PH}" stroke="#536a7f"/><line x1="${L}" y1="${T}" x2="${L}" y2="${T+PH}" stroke="#536a7f"/>${dots}<text x="460" y="390" text-anchor="middle" fill="#536a7f">Superficie mediana (m²)</text><text transform="translate(17 185) rotate(-90)" text-anchor="middle" fill="#536a7f">Renta mensual mediana (MXN)</text></svg>`;
document.querySelector('#rows').innerHTML=a.sort((x,y)=>x.zona.localeCompare(y.zona)).slice(0,500).map(x=>`<tr><td>${esc(x.zona)}</td><td>${x.tipo}</td><td>${x.avisos}</td><td>${x.mediana_area_m2} m²</td><td>${fmt(x.mediana)}</td><td>${fmt(x.p25)} – ${fmt(x.p75)}</td></tr>`).join('');}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function predict(){let a=Math.max(15,Number(document.querySelector('#area').value)||70),house=document.querySelector('#predtype').value==='casa'?1:0;let l=Math.log(a), z=M.coefficients[0]+M.coefficients[1]*(l-M.log_area_mean)/M.log_area_sd+M.coefficients[2]*house;document.querySelector('#prediction').textContent='Estimación: '+fmt(Math.exp(z));}
kind.onchange=draw;search.oninput=draw;document.querySelector('#area').oninput=predict;document.querySelector('#predtype').onchange=predict;draw();predict();
</script></body></html>'''.replace('__DATA__',json.dumps(data,ensure_ascii=False,separators=(',',':')))
