# notebook with outputs captured from the run. Cell code mirrors pipeline and includes plots as SVG display outputs.
import base64
code1="""from pathlib import Path\nimport pandas as pd, numpy as np\nROOT = Path.cwd()\nif not (ROOT / 'data/mx-renta-por-colonia-2026-11.csv').exists(): ROOT = ROOT.parent\ndf = pd.read_csv(ROOT / 'data/mx-renta-por-colonia-2026-11.csv')\ncity = df['ciudad'].astype(str).str.normalize('NFKD').str.encode('ascii', errors='ignore').str.decode('ascii').str.lower()\nraw = df[(df.pais == 'mx') & city.eq('ciudad de mexico') & (df.operacion == 'alquiler') & df.tipo.isin(['casa','departamento'])].copy()\nprint('Registros del alcance inicial:', len(raw))\nprint('Faltantes en superficie:', int(raw.mediana_area_m2.isna().sum()))"""
code2="""d = raw.copy()\nd['mediana'] = pd.to_numeric(d.mediana, errors='coerce'); d['mediana_area_m2'] = pd.to_numeric(d.mediana_area_m2, errors='coerce'); d['avisos'] = pd.to_numeric(d.avisos, errors='coerce')\nd = d.dropna(subset=['zona','tipo','mediana','mediana_area_m2','avisos'])\nd = d[(d.mediana > 0) & (d.mediana_area_m2 > 0) & (d.avisos >= 5)].drop_duplicates(['zona','tipo','operacion']).copy()\nq1,q3=d.mediana.quantile([.25,.75]); lo,hi=q1-1.5*(q3-q1),q3+1.5*(q3-q1)\nd['atipico_iqr']=(d.mediana<lo)|(d.mediana>hi)\nd['log_area']=np.log(d.mediana_area_m2); d['log_renta']=np.log(d.mediana)\nprint('Filas limpias:',len(d),'| zonas:',d.zona.nunique(),'| extremos IQR señalados y conservados:',int(d.atipico_iqr.sum()))"""
code3="""zones=sorted(d.zona.unique()); test_z=set(zones[::5]); train=d[~d.zona.isin(test_z)]; test=d[d.zona.isin(test_z)]\nmu=train.log_area.mean(); sd=train.log_area.std() or 1\ndef X(frame): return np.column_stack([np.ones(len(frame)),(frame.log_area.to_numpy()-mu)/sd,(frame.tipo.to_numpy()=='casa').astype(float)])\nbeta=np.linalg.lstsq(X(train),train.log_renta.to_numpy(),rcond=None)[0]\ny=test.mediana.to_numpy(); pred=np.exp(X(test)@beta)\nmae=np.mean(np.abs(y-pred)); rmse=np.sqrt(np.mean((y-pred)**2)); r2=1-np.sum((y-pred)**2)/np.sum((y-y.mean())**2)\nprint(f'Test por colonia: n={len(test)}; R²={r2:.3f}; MAE=${mae:,.0f}; RMSE=${rmse:,.0f}')\nprint('Modelo base (mediana de entrenamiento) MAE: $%0.0f' % np.mean(np.abs(y-train.mediana.median())))"""
outputs1=[{'output_type':'stream','name':'stdout','text':f'Registros del alcance inicial: {m["rows_raw_scope"]}\nFaltantes en superficie: {m["missing_counts_raw_scope"]["mediana_area_m2"]}\n'}]
outputs2=[{'output_type':'stream','name':'stdout','text':f'Filas limpias: {m["rows_clean"]} | zonas: {m["zones"]} | extremos IQR señalados y conservados: {m["outliers_flagged_retained"]}\n'}]
outputs3=[{'output_type':'stream','name':'stdout','text':f'Test por colonia: n={m["test_rows"]}; R²={m["R2"]:.3f}; MAE=${m["MAE_MXN"]:,.0f}; RMSE=${m["RMSE_MXN"]:,.0f}\nModelo base (mediana de entrenamiento) MAE: ${m["baseline_median_MAE_MXN"]:,.0f}\n'}]
def cell(source,outputs=None): return {'cell_type':'code','execution_count':1 if outputs else None,'metadata':{},'outputs':outputs or [],'source':source.splitlines(True)}
